    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
      last.changes.push(change)
    } else {
      groups.push({ start: change.baseStart, end: change.baseEnd, changes: [change] })
    }
  }

  const regions = []
  let pos = 0
  for (const group of groups) {
    if (group.start > pos) regions.push({ type: 'stable', start: pos, end: group.start })
    regions.push({ type: 'change', start: group.start, end: group.end, changes: group.changes })
    pos = group.end
  }
  if (pos < baseLen) regions.push({ type: 'stable', start: pos, end: baseLen })

  return regions.map(region => resolveRegion(region, base, mine, theirs))
