  const baseLines = base.slice(region.start, region.end)

  if (region.type === 'stable') {
    return { kind: 'stable', lines: baseLines }
  }

  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = sideLines(region, mine, mineChanges, base)
  const theirsLines = sideLines(region, theirs, theirsChanges, base)

  if (arraysEqual(mineLines, theirsLines)) {
    if (mineChanges.length > 0 && theirsChanges.length > 0) return { kind: 'both', lines: mineLines }
    return { kind: mineChanges.length > 0 ? 'mine' : 'theirs', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { kind: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { kind: 'mine', lines: mineLines }
  }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

