  const mode = process.argv[2]
  if (process.argv.length !== 3 || !MODES.includes(mode)) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const raw = await readStdin()
  const docs = splitInput(raw)
  if (!docs) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = docs
  const changesMine = computeChanges(base, mine, 'mine')
  const changesTheirs = computeChanges(base, theirs, 'theirs')
  const resolutions = buildRegions(base, mine, theirs, changesMine, changesTheirs)

  const output = mode === 'regions'
