 * Compute the changes that turn `base` into `side`, using a longest common
 * subsequence over whole lines (compared as exact strings).
 *
 * Ties in the LCS are broken by walking both documents from the start:
 * take a match whenever the current lines are equal, otherwise advance the
 * side whose remaining subsequence (after advancing) is at least as long as
 * the other's, preferring to advance the base when they tie.
 *
 * Every stretch the chosen subsequence does not cover becomes a change: a
 * run of base lines (possibly empty, for an insertion) replaced by a run of
 * `side` lines (possibly empty, for a deletion).
 */
export function computeChanges(base, side, sideName) {
  const m = base.length
  const n = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) dp[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      if (base[i] === side[j]) dp[i][j] = dp[i + 1][j + 1] + 1
      else dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevB = 0
  let prevS = 0
  for (const [bi, si] of matches) {
    if (bi > prevB || si > prevS) {
      changes.push({ baseStart: prevB, baseEnd: bi, sideStart: prevS, sideEnd: si, side: sideName })
    }
    prevB = bi + 1
    prevS = si + 1
  }
  if (prevB < m || prevS < n) {
    changes.push({ baseStart: prevB, baseEnd: m, sideStart: prevS, sideEnd: n, side: sideName })
  }

  return changes
}
